package com.nexuspc.catalog.category;
import com.nexuspc.catalog.dto.*; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/categories") public class CategoryController {private final CategoryService service; public CategoryController(CategoryService s){service=s;} @GetMapping public List<CategoryResponse> all(){return service.all();} @GetMapping("/{slug}") public CategoryResponse get(@PathVariable String slug){return service.get(slug);} @PreAuthorize("hasAnyRole('ADMIN', 'SUPER_ADMIN')") @PostMapping public CategoryResponse create(@Valid @RequestBody CategoryRequest r){return service.create(r);} @PreAuthorize("hasAnyRole('ADMIN', 'SUPER_ADMIN')") @PutMapping("/{id}") public CategoryResponse update(@PathVariable Long id,@Valid @RequestBody CategoryRequest r){return service.update(id,r);} @PreAuthorize("hasAnyRole('ADMIN', 'SUPER_ADMIN')") @DeleteMapping("/{id}") public void delete(@PathVariable Long id){service.delete(id);}}
